]';
if nargin==1;obs=2;end;if obs==10;ColourTemp=ColourTemp10;end

ut=4*XYZWT(1)/(XYZWT(1)+15*XYZWT(2)+3*XYZWT(3));
vt=6*XYZWT(2)/(XYZWT(1)+15*XYZWT(2)+3*XYZWT(3));
dc=((ut-ColourTemp(:,2)).^2+(vt-ColourTemp(:,3)).^2).^0.5;
if ~isnan(min(dc))
eps=1e-8;q=find((dc>=min(dc)-eps) &(dc<=min(dc)+eps));q=q(1);vr=ColourTemp(q,3);
Tm=ColourTemp(q,1);
dm=dc(q);
if Tm~=ColourTemp(end,1) ;
    T1=ColourTemp(q+1,1);
    d1=dc(q+1);
    u1=ColourTemp(q+1,2);
    v1=ColourTemp(q+1,3);
else
    T1=ColourTemp(q,1);
    d1=dc(q);
    u1=ColourTemp(q,2);
    v1=ColourTemp(q,3);
end
if Tm~=ColourTemp(1,1) ;
    T0=ColourTemp(q-1,1);
    d0=dc(q-1);
    u0=ColourTemp(q-1,2);
    v0=ColourTemp(q-1,3);
else
    T0=ColourTemp(q,1);
    d0=dc(q);
    u0=ColourTemp(q,2);
    v0=ColourTemp(q,3);
end
    a=d0/(T0-Tm)/(T0-T1);
    b=dm/(Tm-T0)/(Tm-T1);
    c=d1/(T1-T0)/(T1-Tm);
    A=a+b+c;
    B=-(a*(T1+Tm)+b*(T0+T1)+c*(Tm+T0));
    C=a*Tm*T1+b*T0*T1+c*T0*Tm;
    Tp=-B/(2*A);
    duv=(A*Tp^2+B*Tp+C);
    %signduv=-sign(inhull([ut,vt],ColourTemp([1,q-1,q,q+1,size(ColourTemp,1)],2:3))-0.5);
    signduv=checkduvsign([ut,vt],ColourTemp([q-1,q,q+1],2:3));%fastest
    duv=signduv.*duv;
    
    %triangular solution
    p=((u1-u0)^2+(v1-v0)^2)^0.5;
    p1=(d0^2+p^2-d1^2)/(2*p);
    Pt=T0+p1*(T1-T0)/p;
    p3=(d0^2-p1^2)^0.5;
    p4=Pt;
    Ls=p4+(Tp-p4)*p3*1/0.001;
    if abs(p3)<0.001 %use triangular solution close to BB
        CCT=Ls;
    else
        CCT=Tp; %use parabolic solution further from BB
    end
else
    CCT=NaN;duv=NaN;
end
else
    [CCT,duv]=xyz2CCT(XYZWT,obs);
end
if nargout==3;S=blackbodySPD(CCT);end
end

function signduv=checkduvsign(p,uvm)
% This function takes as arguments two equal-length vectors x and y. p is a
% vector of length 2. The function determines if the point p lies above (+1),
% on (0) or below (-1) the function y = f(x).

%rotate first to ensure p has x between uvm values
p=p-uvm(2,:);uvm=uvm-repmat(uvm(2,:),3,1);
alpha=-atan((uvm(1,2)-uvm(3,2))/(uvm(1,1)-uvm(3,1)));R1=[cos(alpha) -sin(alpha);sin(alpha) cos(alpha)];
uvm=(R1*uvm')';p=(R1*p')';
%plot_2(p,'ro');hold on;plot_2(uvm,'b.-');

x=uvm(:,1);y=uvm(:,2);
ux = min(x(x > p(1))); lx = max(x(x < p(1)));
if isempty(ux) | isempty(lx)
    %plot_2(p,'ro');hold on;plot_2(uvm,'b.-');
    signduv=sign(p(2));
else

uy = y(x == ux);
ly = y(x == lx);

if lx ~= ux
   s=(uy-ly)/(ux-lx)*(p(1)-lx)+ly;
else
   s = uy;
end
signduv = sign(p(2) - s);
end
end